<template>
  <div class="designer-projects" v-loading="loading">
    <header class="designer-project-head">
      <div><span class="designer-eyebrow">PROJECT MANAGEMENT</span><h1>项目管理</h1><p>跟进负责项目、推进阶段确认，并集中处理待交付内容。</p></div>
    </header>
    <section class="designer-project-stats"><div><span>负责项目</span><strong>{{ projects.length }}</strong></div><div><span>等待客户确认</span><strong>{{ pendingCount }}</strong></div><div><span>当前进行中</span><strong>{{ inProgressCount }}</strong></div></section>
    <div class="designer-filter"><el-input v-model="filters.keyword" :prefix-icon="Search" clearable placeholder="搜索项目名称或客户" /><el-select v-model="filters.status" clearable placeholder="项目状态"><el-option label="进行中" value="IN_PROGRESS" /><el-option label="已完成" value="COMPLETED" /><el-option label="已暂停" value="PAUSED" /></el-select><button type="button" @click="load">筛选</button><button type="button" class="reset" @click="Object.assign(filters, { keyword: '', status: '' }); load()">重置</button></div>
    <div class="designer-project-grid"><article v-for="project in projects" :key="project.id" class="designer-project-card" @click="router.push(`/projects/${project.id}`)"><header><span :class="project.status.toLowerCase()">{{ statusName(project.status) }}</span><time>{{ formatDate(project.updatedAt) }}</time></header><h2>{{ project.name }}</h2><p>{{ project.description || '暂无项目说明' }}</p><div class="designer-stage"><span>当前阶段</span><strong>{{ project.currentStageName }}</strong></div><div class="designer-progress"><i :style="{ width: `${project.progress}%` }"></i></div><footer><b>{{ project.progress }}%</b><span>{{ project.customerName || '客户' }}</span><el-icon><ArrowRight /></el-icon></footer></article></div>
    <div v-if="!loading && !projects.length" class="designer-project-empty">没有匹配的项目。</div>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { ArrowRight, Search } from '@element-plus/icons-vue'
import { listProjects } from '@/api'
import type { ProjectVO } from '@/models'
import { projectStatusLabel } from '@/utils/displayLabels'

const router = useRouter(); const loading = ref(false); const projects = ref<ProjectVO[]>([]); const filters = reactive({ keyword: '', status: '' })
const pendingCount = computed(() => projects.value.filter((item) => item.currentStage && item.status === 'IN_PROGRESS').length)
const inProgressCount = computed(() => projects.value.filter((item) => item.status === 'IN_PROGRESS').length)
const statusName = projectStatusLabel
const formatDate = (value?: string) => value ? value.replace('T', ' ').slice(0, 10) : ''
async function load() { loading.value = true; try { projects.value = (await listProjects({ keyword: filters.keyword || undefined, status: filters.status || undefined, page: 1, size: 50 })).records } catch (error) { ElMessage.error(error instanceof Error ? error.message : '项目加载失败') } finally { loading.value = false } }
onMounted(load)
</script>

<style>
.designer-projects { min-height: calc(100vh - 111px); }.designer-project-head { padding: 13px 0 25px; display: flex; align-items: flex-end; justify-content: space-between; gap: 25px; }.designer-eyebrow { color: #087b76; font-size: 11px; font-weight: 800; letter-spacing: 1px; }.designer-project-head h1 { margin: 7px 0; font-size: 30px; }.designer-project-head p { margin: 0; color: #748398; font-size: 14px; }.designer-workbench-link { min-height: 38px; padding: 0 13px; border: 1px solid #b8ded9; display: inline-flex; align-items: center; gap: 5px; background: #fff; color: #087b76; cursor: pointer; font-size: 13px; font-weight: 700; }.designer-project-stats { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); border: 1px solid #dce6ee; background: #fff; }.designer-project-stats div { padding: 16px 20px; border-right: 1px solid #e6edf3; display: grid; gap: 5px; }.designer-project-stats div:last-child { border: 0; }.designer-project-stats span { color: #8190a2; font-size: 12px; }.designer-project-stats strong { color: #26384a; font-size: 25px; }.designer-filter { margin-top: 16px; padding: 10px; border: 1px solid #dce6ee; display: grid; grid-template-columns: minmax(240px, 1fr) 200px auto auto; gap: 9px; background: #fff; }.designer-filter .el-input__wrapper, .designer-filter .el-select__wrapper { min-height: 38px; box-shadow: none; background: #f5f8fb; }.designer-filter button { min-width: 64px; border: 0; background: #087b76; color: white; cursor: pointer; font-size: 13px; }.designer-filter button.reset { background: transparent; color: #64758a; }.designer-project-grid { margin-top: 16px; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 15px; }.designer-project-card { min-height: 221px; padding: 17px; border: 1px solid #dce6ee; background: #fff; cursor: pointer; transition: transform .18s ease, box-shadow .18s ease; }.designer-project-card:hover { transform: translateY(-3px); box-shadow: 0 15px 30px rgba(24, 55, 66, .11); }.designer-project-card header, .designer-project-card footer { display: flex; align-items: center; justify-content: space-between; }.designer-project-card header span { padding: 3px 7px; background: #e7f4f3; color: #087b76; font-size: 11px; font-weight: 700; }.designer-project-card header span.completed { background: #e5f4e9; color: #29784a; }.designer-project-card header span.paused { background: #fff1cf; color: #976400; }.designer-project-card time { color: #9aa6b4; font-size: 11px; }.designer-project-card h2 { margin: 21px 0 7px; font-size: 17px; }.designer-project-card p { min-height: 38px; margin: 0; color: #758398; font-size: 12px; line-height: 1.65; }.designer-stage { margin-top: 17px; display: flex; justify-content: space-between; gap: 9px; color: #7d8c9e; font-size: 12px; }.designer-stage strong { color: #405367; }.designer-progress { height: 5px; margin-top: 9px; overflow: hidden; background: #e9eff3; }.designer-progress i { height: 100%; display: block; background: #087b76; }.designer-project-card footer { margin-top: 9px; color: #8695a6; font-size: 11px; }.designer-project-card footer b { color: #087b76; font-size: 13px; }.designer-project-empty { margin-top: 16px; padding: 70px; border: 1px dashed #cbd8e3; color: #8795a7; text-align: center; }
@media (max-width: 900px) { .designer-project-grid { grid-template-columns: 1fr 1fr; }.designer-filter { grid-template-columns: 1fr 1fr; }.designer-filter > :first-child { grid-column: 1 / -1; } } @media (max-width: 580px) { .designer-project-head { align-items: flex-start; flex-direction: column; }.designer-project-grid { grid-template-columns: 1fr; }.designer-project-stats { grid-template-columns: 1fr; }.designer-project-stats div { border-right: 0; border-bottom: 1px solid #e6edf3; } }
</style>
